const D = { density: .55, energy: .55, speed: 1, scale: 1, hue: 278, x: .5, y: .5, eta: 2.2, style: 'electric', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const st = P.style;
const intn = (K.intensity!=null?K.intensity:.6);
const ax = clp(P.x,0.08,0.92), ay = clp(P.y,0.08,0.92);

// ---- grid (roughly square cells, capped within PROBE budget) ----
let COLS, ROWS; const ar = width/height;
if (ar>=1){ ROWS = 60; COLS = clp(Math.round(60*ar),40,122); }
else { COLS = 60; ROWS = clp(Math.round(60/ar),40,122); }
const cw = width/COLS, ch = height/ROWS;
const NC = COLS*ROWS;

// ---- HSB->RGB for drawingContext strokes (buffer draws in raw rgba) ----
function hsb2rgb(h,s,b){ h=((h%360)+360)%360; s=clp(s,0,100)/100; b=clp(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h/60)%2-1)), m=b-c; let r,g,bl;
  if(h<60){r=c;g=x;bl=0;} else if(h<120){r=x;g=c;bl=0;} else if(h<180){r=0;g=c;bl=x;}
  else if(h<240){r=0;g=x;bl=c;} else if(h<300){r=x;g=0;bl=c;} else {r=c;g=0;bl=x;}
  return [Math.round((r+m)*255),Math.round((g+m)*255),Math.round((bl+m)*255)]; }

// ---- ground palette per style (radial vignette: warm/violet core -> dark edge) ----
function groundCfg(s){
  if(s==='acrylic') return {h:190,sat:78,cB:30,mB:14,eB:8};
  if(s==='woodburn')return {h:26, sat:60,cB:46,mB:30,eB:17};
  if(s==='frost')   return {h:208,sat:66,cB:32,mB:16,eB:9};
  if(s==='ink')     return {h:42, sat:12,cB:88,mB:82,eB:72};
  return {h:272,sat:72,cB:34,mB:15,eB:8}; // electric
}
function paintGround(g, alpha){
  const ctx=g.drawingContext, gs=S.gs;
  const cx=ax*g.width, cy=ay*g.height, R=Math.hypot(g.width,g.height)*0.92;
  const gr=ctx.createRadialGradient(cx,cy,R*0.02,cx,cy,R);
  const c0=hsb2rgb(gs.h,gs.sat*0.7,gs.cB), c1=hsb2rgb(gs.h,gs.sat,gs.mB), c2=hsb2rgb(gs.h,gs.sat,gs.eB);
  gr.addColorStop(0,   'rgba('+c0[0]+','+c0[1]+','+c0[2]+','+alpha+')');
  gr.addColorStop(0.45,'rgba('+c1[0]+','+c1[1]+','+c1[2]+','+alpha+')');
  gr.addColorStop(1,   'rgba('+c2[0]+','+c2[1]+','+c2[2]+','+alpha+')');
  ctx.save(); ctx.globalCompositeOperation='source-over'; ctx.fillStyle=gr; ctx.fillRect(0,0,g.width,g.height); ctx.restore();
}

// ---- vein color ramp along depth (0 core .. 1 tip) ----
const ho = (P.hue-278) + K.section*3;
function vein(t){
  let h,s,b,hc,sc,bc,blur;
  if(st==='acrylic'){ h=189+ho; s=28+58*t; b=98-16*t; hc=186+ho; sc=6+18*t; bc=100; blur=1; }
  else if(st==='woodburn'){ h=46-26*t+ho; s=62+34*t; b=100-46*t; hc=50-16*t+ho; sc=40+28*t; bc=100-12*t; blur=1; }
  else if(st==='frost'){ h=202+ho; s=8+42*t; b=100-10*t; hc=200+ho; sc=2+14*t; bc=100; blur=0.5; }
  else if(st==='ink'){ h=40+ho; s=10; b=24-12*t; hc=40+ho; sc=8; bc=16-8*t; blur=0; }
  else { h=278+ho; s=30+60*t; b=100-14*t; hc=278+ho; sc=8+22*t; bc=100; blur=1; } // electric
  return { bloom: hsb2rgb(h,s,b), core: hsb2rgb(hc,sc,bc), blur };
}
function stampSeg(x0,y0,x1,y1,depth){
  const t=clp(depth/85,0,1), v=vein(t), ctx=S.buf.drawingContext;
  const w = u*(0.0014 + 0.0060*Math.exp(-depth*0.05))*(0.6+P.scale*0.6);
  ctx.save(); ctx.lineCap='round';
  const glow = v.blur*(4+10*P.energy);
  if(glow>0){ ctx.shadowBlur=glow; ctx.shadowColor='rgba('+v.core[0]+','+v.core[1]+','+v.core[2]+',0.9)'; }
  ctx.strokeStyle='rgba('+v.bloom[0]+','+v.bloom[1]+','+v.bloom[2]+','+(st==='ink'?0.9:0.22)+')';
  ctx.lineWidth = w*(st==='ink'?1:2.6);
  ctx.beginPath(); ctx.moveTo(x0,y0); ctx.lineTo(x1,y1); ctx.stroke();
  if(st!=='ink'){ ctx.shadowBlur=glow*0.4;
    ctx.strokeStyle='rgba('+v.core[0]+','+v.core[1]+','+v.core[2]+',0.92)';
    ctx.lineWidth=Math.max(0.6,w); ctx.beginPath(); ctx.moveTo(x0,y0); ctx.lineTo(x1,y1); ctx.stroke(); }
  ctx.shadowBlur=0; ctx.restore();
}

// ---- candidate helper ----
function addCand(x,y){
  const nb=[[1,0],[-1,0],[0,1],[0,-1]];
  for(let n=0;n<4;n++){ const nx=x+nb[n][0], ny=y+nb[n][1];
    if(nx<1||nx>=COLS-1||ny<1||ny>=ROWS-1) continue;
    const i=ny*COLS+nx; if(S.occ[i]||S.inCand[i]) continue; S.inCand[i]=1; S.cand.push(i); }
}
function seedAt(sx,sy){ sx=clp(sx,2,COLS-3)|0; sy=clp(sy,2,ROWS-3)|0;
  const i=sy*COLS+sx; if(S.occ[i]) return; S.occ[i]=1; S.phi[i]=0; S.dep[i]=0; S.par[i]=-1; addCand(sx,sy); }

// ---- sim (re)build ----
function resetSim(hard){
  S.occ=new Uint8Array(NC); S.phi=new Float32Array(NC); S.par=new Int32Array(NC).fill(-1);
  S.dep=new Int32Array(NC); S.inCand=new Uint8Array(NC); S.cand=[];
  for(let i=0;i<NC;i++) S.phi[i]=0.5;
  for(let x=0;x<COLS;x++){ S.phi[x]=1; S.phi[(ROWS-1)*COLS+x]=1; }
  for(let y=0;y<ROWS;y++){ S.phi[y*COLS]=1; S.phi[y*COLS+COLS-1]=1; }
  const jx=(S.rnd()-0.5)*0.12, jy=(S.rnd()-0.5)*0.12;
  seedAt(Math.round((ax+jx)*COLS), Math.round((ay+jy)*ROWS));
  S.recent=[];
}

const period = 30;
const epoch = Math.floor(K.t/period);
const hardKey = width+'x'+height+'|'+P.seed+'|'+st;
if (S.hardKey !== hardKey){
  S.hardKey = hardKey; S.epoch = epoch;
  let z=((P.seed*2654435761)^(epoch*40503)^0x5b)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  if(!S.buf || S.bufKey!==width+'x'+height){ if(S.buf) S.buf.remove();
    S.buf=createGraphics(width,height); S.buf.pixelDensity(1); S.bufKey=width+'x'+height; }
  S.gs=groundCfg(st); paintGround(S.buf,1); resetSim(true);
} else if (S.epoch !== epoch){
  S.epoch = epoch;
  let z=((P.seed*2654435761)^(epoch*40503)^0x5b)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  resetSim(false); // soft: buffer keeps old figure, it fades out under the new one
}

// ---- per-frame slow fade: the burn ACCRETES & persists (~10s half-life), then
//      soft-turns-over so the next epoch regrows without a hard clear (no strobe) ----
paintGround(S.buf, 0.0011);

// ---- relax potential field (Jacobi), occupied pinned 0, frame source pinned 1 ----
const phi=S.phi, occ=S.occ;
const sweeps = 2 + (P.speed>2?1:0);
for(let s=0;s<sweeps;s++) for(let y=1;y<ROWS-1;y++) for(let x=1;x<COLS-1;x++){ const i=y*COLS+x;
  if(occ[i]){ phi[i]=0; continue; }
  phi[i]=0.25*(phi[i-1]+phi[i+1]+phi[i-COLS]+phi[i+COLS]); }

// ---- grow G cells/frame, weighted by phi^eta (dielectric breakdown) ----
const eta = clp(P.eta,0.6,7);
let G = Math.round((0.6+P.speed*1.6)*(0.5+intn) + A.bass*4);
G = Math.round(clp(G,1,10)*(0.4+P.density*1.2)); G = clp(G,1,12);
if(S.cand.length===0){ // reseed a fresh nucleus so the burn keeps accreting
  const rx=1+Math.floor(S.rnd()*(COLS-2)), ry=1+Math.floor(S.rnd()*(ROWS-2));
  if(!occ[ry*COLS+rx]) seedAt(rx,ry);
}
for(let gi=0; gi<G && S.cand.length; gi++){
  let sum=0; const cand=S.cand, m=cand.length, wts=new Float64Array(m);
  for(let k=0;k<m;k++){ const w=Math.pow(Math.max(1e-4,phi[cand[k]]),eta); wts[k]=w; sum+=w; }
  let r=S.rnd()*sum, pick=0; for(let k=0;k<m;k++){ r-=wts[k]; if(r<=0){pick=k;break;} }
  const ci=cand[pick]; cand[pick]=cand[m-1]; cand.pop(); S.inCand[ci]=0;
  if(occ[ci]) continue;
  occ[ci]=1; phi[ci]=0; const x=ci%COLS, y=(ci/COLS)|0;
  const nb=[[1,0],[-1,0],[0,1],[0,-1]]; let par=-1;
  for(let n=0;n<4;n++){ const j=(y+nb[n][1])*COLS+(x+nb[n][0]); if(j>=0&&j<NC&&occ[j]){par=j;break;} }
  S.par[ci]=par; const dp=(par>=0? S.dep[par]+1 : 0); S.dep[ci]=dp;
  if(par>=0){ const px=(par%COLS)*cw+cw/2, py=((par/COLS)|0)*ch+ch/2;
    stampSeg(px,py, x*cw+cw/2, y*ch+ch/2, dp); }
  addCand(x,y);
  S.recent.push(ci); if(S.recent.length>160) S.recent.shift();
}

// ---- draw accumulated burn with slow K.t drift (never re-phases: motion floor) ----
push();
const scl = 1.08 + 0.012*Math.sin(K.t*0.06);
const dx = Math.sin(K.t*0.13)*u*0.02, dy = Math.cos(K.t*0.10)*u*0.018;
translate(width/2+dx, height/2+dy); rotate(Math.sin(K.t*0.017)*0.02);
imageMode(CENTER); if(P.alpha<100) tint(0,0,100,P.alpha);
image(S.buf, 0,0, width*scl, height*scl);
imageMode(CORNER); noTint(); pop();

// ---- hot core: pulsing radial glow at the injection seed ----
const glowStyle = (st==='ink')?0:(st==='frost')?0.55:1;
if(glowStyle>0){
  const corePulse = 0.6+0.4*Math.sin(K.t*1.7) + 0.5*K.pulse + A.bass*0.8;
  const cpx=ax*width, cpy=ay*height;
  const cr = u*(0.10+0.05*Math.sin(K.t*0.9))*(0.7+P.energy*0.8)*(0.7+P.scale*0.5);
  const chb = hsb2rgb((st==='woodburn'?42:st==='acrylic'?186:st==='frost'?200:280)+(P.hue-278), 22, 100);
  const dctx=drawingContext;
  dctx.save(); dctx.globalCompositeOperation='lighter';
  const cg=dctx.createRadialGradient(cpx,cpy,1,cpx,cpy,cr);
  const a0=clp(0.5*P.energy*(0.6+corePulse*0.3)*glowStyle,0,0.8);
  cg.addColorStop(0,'rgba('+chb[0]+','+chb[1]+','+chb[2]+','+a0+')');
  cg.addColorStop(1,'rgba('+chb[0]+','+chb[1]+','+chb[2]+',0)');
  dctx.fillStyle=cg; dctx.fillRect(cpx-cr,cpy-cr,cr*2,cr*2); dctx.restore();
}

// ---- creeping-leader shimmer at the active frontier (continuous, silence-safe) ----
push(); blendMode(ADD); noStroke();
const fh=(st==='woodburn'?40:st==='frost'?200:st==='acrylic'?186:st==='ink'?42:282)+(P.hue-278);
const lim=Math.min(S.cand.length,150);
for(let k=0;k<lim;k++){ const i=S.cand[k], x=i%COLS, y=(i/COLS)|0;
  const fl=Math.pow(clp(phi[i],0,1),1.3)*(0.55+0.45*Math.sin(K.t*3.1 + k*0.7));
  const gA=fl*(14+A.treble*40)*(0.4+P.energy)*(st==='ink'?0.22:1);
  if(gA<0.6) continue;
  fill(fh, st==='ink'?14:st==='frost'?34:70, 100, gA);
  circle(x*cw+cw/2, y*ch+ch/2, cw*(1.1+fl*1.6)); }
blendMode(BLEND); pop();
drawingContext.shadowBlur=0;
